}
function botsRelease(PDO $db,int $project,?int $release): ?array {
 if($release===null)return null;$r=releaseRow($db,$project,$release);if($r['state']!=='confirmed'||!is_string($r['evidence'])||!is_string($r['evidence_hash'])||!hash_equals($r['evidence_hash'],hash('sha256',$r['evidence'])))throw new Problem('Требуется подтверждённый выпуск с целостными доказательствами.',409);return $r;
}
function botsRow(PDO $db,int $project,int $id): array {return entity($db,'SELECT * FROM bots_messages WHERE project_id=? AND id=?',[$project,$id]);}
function botsEvent(PDO $db,array $r,int $actor,string $state,string $detail=''): void {
 query($db,'INSERT INTO bots_events(project_id,message_id,actor_id,state,detail,created_at) VALUES(?,?,?,?,?,?)',[$r['project_id'],$r['id'],$actor,$state,$detail,time()]);
 auditEvent($db,['id'=>$actor,'organization_id'=>$r['organization_id']],(int)$r['project_id'],'bots.'.$state,(int)$r['id'],$detail);
}
function botsPreviewHash(array $r,?array $support=null): string {$parts=[$r['remote_id'],$r['identity_hash'],$r['target_revision'],$r['release_id']===null?null:(int)$r['release_id'],$r['release_hash'],$r['message_hash']];if($support!==null)$parts[]=$support;return hash('sha256',json_encode($parts,JSON_THROW_ON_ERROR));}
function botsAssertSnapshot(PDO $db,array $r,array $b): void {
 $link=botsSupportLink($db,(int)$r['project_id'],(int)$r['id']);botsSupportAssert($db,$r,$link);
 if(!hash_equals($r['identity_hash'],$b['identity_hash'])||!hash_equals($r['message_hash'],hash('sha256',$r['message']))||!hash_equals($r['preview_hash'],botsPreviewHash($r,$link)))throw new Problem('Снимок сообщения изменён.',409);
 $rel=botsRelease($db,(int)$r['project_id'],$r['release_id']===null?null:(int)$r['release_id']);if($rel&&!hash_equals($r['release_hash'],$rel['evidence_hash']))throw new Problem('Выпуск изменён.',409);
}
function botsDraft(PDO $db,array $u,int $project,string $key,?int $release,mixed $message,?callable $transport=null,?int $support=null): int {
 $u=botsActor($db,$u,$project);if(!preg_match('/\A[a-f0-9]{32}\z/D',$key))throw new Problem('Обновите форму.');$text=botsText($message);$b=botsBinding($db,$project);if(!$b||!(int)$b['active'])throw new Problem('Bots отключён.',409);$c=botsBound($b);$rel=botsRelease($db,$project,$release);if($release!==null&&$support!==null)throw new Problem('Выберите выпуск или запрос поддержки.');$link=botsSupportSnapshot($db,$project,$support);
