/** All mutations except the HTTP handoff are serialized with the application write lock. */
function botsCommand(PDO $db,array $u,int $project,int $id,string $op,string $preview,mixed $reason=null,?int $expectedEvent=null): void {
 atomic($db,function()use($db,$u,$project,$id,$op,$preview,$reason,$expectedEvent){$u=botsActor($db,$u,$project);$r=botsRow($db,$project,$id);if(!hash_equals($r['preview_hash'],$preview))throw new Problem('Предпросмотр изменён.',409);$b=botsBinding($db,$project);$state=$r['state'];$command=$r['command'];$next='queued';$detail=$op;
