  elseif($op==='close'){if($state==='closed')return;if($state!=='uncertain')throw new Problem('Закрывается только неизвестный результат.',409);$latest=(int)query($db,'SELECT MAX(id) FROM bots_events WHERE project_id=? AND message_id=?',[$project,$id])->fetchColumn();if($expectedEvent!==$latest)throw new Problem('История доставки изменилась. Обновите карточку.',409);$detail='manual_close: '.word($reason,300,'Основание сверки');$next='closed';}
